WITH valid AS (SELECT *, LOWER(status) status_lower FROM payments WHERE paid_at > TIMESTAMP '2023-08-23 15:00:00'), with_prev AS (SELECT *, LAG(paid_at) OVER (PARTITION BY order_id ORDER BY paid_at, id) AS prev_paid_at FROM valid), with_gaps AS (SELECT *, CASE WHEN prev_paid_at IS NULL OR paid_at > prev_paid_at + INTERVAL '7' DAY THEN 1 ELSE 0 END AS session_start_flag FROM with_prev), sessions_payments AS (SELECT id, order_id, method, paid_at, SUM(session_start_flag) OVER (PARTITION BY order_id ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM with_gaps) SELECT DATE_TRUNC('MONTH', paid_at) AS activity_month, CASE WHEN session_no >= 8 THEN 'HIGH' ELSE 'LOW' END AS session_no_tier, COUNT(*) FILTER (WHERE method = 'promptpay') AS promptpay_rows, COUNT(*) FILTER (WHERE method = 'bank_transfer') AS bank_transfer_rows, COUNT(CASE WHEN method = 'card' THEN 1 END) AS card_count, GROUPING(DATE_TRUNC('MONTH', paid_at)) AS grouping_id FROM sessions_payments GROUP BY ROLLUP (DATE_TRUNC('MONTH', paid_at), CASE WHEN session_no >= 8 THEN 'HIGH' ELSE 'LOW' END) ORDER BY session_no_tier;
